            actual_before = self._state_summary(self._snapshot_state())
            if not hmac.compare_digest(
                actual_before, frame["before"]
            ) or not hmac.compare_digest(
                frame["before"], expected_before
            ):
                raise ValueError(
                    f"journal frame {frame['seq']}: before-state "
                    "summary does not match the replayed state"
                )
        try:
            if op == "create":
                if params["name"] in self._heads:
                    raise ValueError(
                        f"branch {params['name']!r} already exists"
                    )
                self.create(params["name"], params["from_event"])
            elif op == "append":
                if params["id"] in self._appends.get(params["name"], {}):
                    raise ValueError(
                        f"event {params['id']!r} is already recorded"
                    )
                self.append(
                    params["name"],
                    params["id"],
                    params["at"],
                    dict(params["changes"]),
                )
            else:
                if params["id"] in self._merges:
                    raise ValueError(
                        f"merge {params['id']!r} is already recorded"
                    )
                self.merge(
                    params["target"],
                    params["source"],
                    params["id"],
                    params["at"],
                    dict(params["changes"]),
                )
        except (KeyError, ValueError) as exc:
            raise ValueError(
                f"journal frame {frame['seq']} does not replay "
                f"cleanly: {exc}"
            ) from exc
        if "after" in frame:
            actual_after = self._state_summary(self._snapshot_state())
            if not hmac.compare_digest(actual_after, frame["after"]):
                raise ValueError(
                    f"journal frame {frame['seq']}: after-state "
                    "summary does not match the replayed state"
                )
